  const DES={columna:'Lleva la carga de la cubierta hasta la placa base y los anclajes.',viga:'Viga del cuadro principal: recibe las correas y las lleva a las columnas.',correa:'Soporta la lámina de cubierta y reparte su peso a las vigas.',pie_amigo:'Acorta la luz libre de la viga y rigidiza el nudo con la columna.',cercha:'Transfiere la carga de una columna eliminada, liberando el área de circulación.',placa_base:'Placa con cartelas y pernos que fija la columna al dado.',placa_tapa:'Cierre superior de la columna.',dado:'Dado de concreto que recibe los pernos de anclaje.'};
  const KC={columna:C.plata,viga:C.acero,correa:C.correa,pie_amigo:C.oro,cercha:C.oro2,placa_base:0x8a8a8a,placa_tapa:0x8a8a8a,dado:C.dado};
  const mem=[];
  for(const r of D.m){const kind=KN[r[0]],a=r.slice(8,17);
    const e0=P(a[0],a[1],a[2]),e1=P(a[3],a[4],a[5]),e2=P(a[6],a[7],a[8]);
    if(new T.Matrix4().makeBasis(e0,e1,e2).determinant()<0)e0.negate();
    const m=k.box(P(r[2],r[3],r[4]),r[6],r[7],r[5],KC[kind]);
    m.quaternion.setFromRotationMatrix(new T.Matrix4().makeBasis(e0,e1,e2));
    m.userData.info={t:NOM[kind]+' '+r[1].replace(/^(PB|PT|DADO)-/,''),d:DES[kind]};
    mem.push({m,kind,u:r[17]});}
  const roof=new T.Group(),walls=new T.Group(),cargas=new T.Group();k.root.add(roof,walls,cargas);
  D.r.forEach(q=>k.quad([0,1,2,3].map(i=>P(q[i*3],q[i*3+1],q[i*3+2]+.16)),0xc5ccd3,.82,roof));
  D.w.forEach(w=>{const a=P(w[0],w[1],0),b=P(w[2],w[3],0),Lw=a.distanceTo(b);if(Lw<.1)return;const m=k.box(a.clone().add(b).multiplyScalar(.5).setY(w[4]/2),Lw,w[4],.25,0x2b2d30,walls,{transparent:true,opacity:.4});m.rotation.y=-Math.atan2(b.z-a.z,b.x-a.x);});
  const arr=[];D.r.forEach((q,i)=>{if(i%2)return;const c=P((q[0]+q[6])/2,(q[1]+q[7])/2,(q[2]+q[8])/2);const g=k.arrow(c.clone().add(V(0,1.35,0)),c.clone().add(V(0,.2,0)),C.mal,.035,cargas);arr.push(g);});
  const Nmax=Math.max(...D.c.map(c=>c[3]));
  D.c.forEach(c=>{const len=.7+2.3*c[3]/Nmax,x=c[1],z=c[2];k.arrow(V(x,-.75-len,z),V(x,-.72,z),C.ok,.06,cargas);k.label(c[0],V(x,-.85-len,z),cargas);});
  const paths=mem.filter(o=>o.kind==='columna').map(o=>{const p=o.m.position;return[V(p.x,p.y+o.m.geometry.parameters.depth/2,p.z),V(p.x,.1,p.z)];});
  k.flow(paths,C.oro,{n:170,speed:1.7,size:.34},cargas);
  k.label('Cercha de transferencia',P(4.75,-10.13,6.9),walls);
  return{modo(id){roof.visible=id==='cubierta';cargas.visible=id==='cargas';walls.visible=id!=='utilizacion';
      mem.forEach(o=>{if(id==='utilizacion')k.col(o.m,o.u>=0?heat(o.u):0x55585d);else if(id==='cargas')k.col(o.m,0x55585d);else k.reset(o.m);});},
    tick(t){if(cargas.visible)arr.forEach((g,i)=>g.position.y=-.14*Math.abs(Math.sin(t*2.4+i*.6)));}};
