  for(const z of [0,6])exM.push(k.bar(V(0,H,z),V(8,H,z),.16,.3,C.acero,ex));
  for(const x of [0,4,8])exM.push(k.bar(V(x,H,0),V(x,H,6),.16,.3,C.acero,ex));
  for(const x of [2,6])exM.push(k.bar(V(x,H,0),V(x,H,6),.1,.2,C.correa,ex));
