  LN.forEach(l=>l.y=yb+l.r);
  const [a,b,c]=LN;
  a.pts=[V(-3,a.y,.9),V(13.2,a.y,.9),V(13.2,a.y,-2.6),V(16.8,a.y,-2.6),V(16.8,a.y,.9),V(31.6,a.y,.9),V(31.6,2.5,.9),V(33.3,2.5,.9)];
  b.pts=[V(-3,b.y,2),V(31,b.y,2),V(31,.75,2),V(32.7,.75,2)];
  c.pts=[V(-3,c.y,3.1),V(24.6,c.y,3.1),V(24.6,.8,3.1),V(25.9,.8,3.1)];
  const net=new T.Group(),sup=new T.Group(),rea=new T.Group(),exg=new T.Group();k.root.add(net,sup,rea,exg);
  LN.forEach(l=>{l.p=k.pipe(l.pts,l.r,l.c,net,{max:1});k.cyl(l.pts[0].clone(),l.r*1.7,.08,0x8a8a8a,net,'x');});
  k.cyl(V(34.6,2.6,.9),1.2,5.2,0xb9bec4,null);k.sph(V(34.6,5.2,.9),1.2,0xb9bec4).scale.y=.45;
  k.cyl(V(33.25,.75,2),.45,.5,0x9b111e,null,'z');k.box(V(34.3,.75,2),1.2,.6,.6,0x4a5560);k.box(V(33.8,.22,2),2.8,.2,1.1,0x3a3c40);
  k.box(V(26.3,.8,3.1),.55,.45,.45,0x6b6e72);
  k.valve(V(28,a.y,.9),'x',a.r,0x8a8a8a,net);k.valve(V(29,b.y,2),'x',b.r,0x8a8a8a,net);k.valve(V(22,c.y,3.1),'x',c.r*1.3,0x8a8a8a,net);
  const sp=[];
  LN.forEach((l,li)=>{for(const x of bents){if(li===2&&x>24)continue;
    const tp=l.an.includes(x)?'an':l.gu.includes(x)?'gu':'ap';const y0=5.125;
    if(tp==='an'){sp.push(k.box(V(x,y0+.12,l.z),.5,.24,.5,C.oro,sup));}
    else{sp.push(k.box(V(x,y0+.05,l.z),.36,.1,.3,0x9aa1a8,sup));if(tp==='gu')for(const s of [-1,1])sp.push(k.box(V(x,y0+.18,l.z+s*(l.r+.07)),.3,.26,.04,C.cian,sup));}
    if(tp==='an'){for(const s of [-1,1])k.arrow(V(x+s*1.4,l.y,l.z),V(x+s*.32,l.y,l.z),C.oro,.05,rea);}
    else k.arrow(V(x,l.y+1.1,l.z),V(x,l.y+l.r+.06,l.z),C.ok,.045+l.r*.1,rea);
    if(tp==='gu')k.arrow(V(x,l.y,l.z+1),V(x,l.y,l.z+l.r+.1),C.cian,.04,rea);}});
  LN.forEach(l=>{l.f=k.flow([l.pts],l.c,{n:l.r>.15?170:130,speed:l.r>.15?4:2.5,size:.5});});
  const spc=[];LN.forEach(l=>{l.pts.slice(1,-1).forEach(p=>spc.push(p));l.an.forEach(x=>spc.push(V(x,l.y,l.z)));});
  LN.forEach(l=>l.p.all.forEach(s=>{let v=.16;spc.forEach(p=>v+=.75*Math.exp(-s.mid.distanceTo(p)/1.6));s.st=Math.min(1,v);}));
  const ref=[];a.pts.forEach((p,i)=>{if(i===0){ref.push(p);return;}const q=a.pts[i-1],n=Math.max(1,Math.ceil(q.distanceTo(p)/1));for(let j=1;j<=n;j++)ref.push(q.clone().lerp(p,j/n));});
  const ep=new Poly(ref.length,a.r,C.oro,exg);
  for(const x of a.an)k.label('Anclaje',V(x,a.y+.9,a.z),exg);k.label('Lazo de expansión',V(15,a.y+1.2,-2.6),exg);
  k.label('Vapor',V(-2.6,a.y+.6,.9),net);k.label('Agua de proceso',V(-2.6,b.y+.95,2),net);k.label('Condensado',V(-2.6,c.y+1.3,3.1),net);
