  for(const [p,q] of [[[0,0],[30,0]],[[0,20],[30,20]],[[0,0],[0,20]],[[30,0],[30,20]],[[10,0],[10,20]],[[20,0],[20,20]]])k.bar(V(p[0],9,p[1]),V(q[0],9,q[1]),.2,.4,B);
  const rk=0x2f5d8a;
  for(const zr of [4.5,10,15.5]){for(let i=0;i<=10;i++){const x=3+2.4*i;for(const s of [-.55,.55])k.bar(V(x,0,zr+s),V(x,6,zr+s),.08,.08,rk);}
    for(let i=0;i<10;i++)for(const y of [.8,2.8,4.8])k.box(V(4.2+2.4*i,y,zr),2.2,1.4,1,(i+y|0)%2?0x8a6d3b:0x6b5a3a);}
  k.box(V(-7,-.05,4),10,.1,8,0x1b1c1e);
  k.cyl(V(-9.5,3.5,4),2.4,7,0xb9bec4);k.sph(V(-4.8,.6,4),.45,0x9b111e);k.box(V(-4.8,.6,5.3),.8,.8,1.6,0x4a5560);
  k.sph(V(-4.8,.42,2.2),.24,0x9b111e);k.box(V(-4.8,.42,2.85),.45,.45,.8,0x4a5560);k.box(V(-2.6,1.1,6.8),.3,1.6,1,C.rojo);
  const pr=new T.Group();k.root.add(pr);const R=C.rojo,runs=[];
  k.pipe([V(-7.1,.6,4),V(-5.25,.6,4)],.12,0x7a1d24,pr);k.pipe([V(-4.8,.42,1.95),V(-3.4,.42,1.95),V(-3.4,.6,4)],.04,R,pr);
  const dis=k.pipe([V(-4.35,.6,4),V(-1.2,.6,4),V(-1.2,.6,1),V(1,.6,1)],.1,R,pr);runs.push(dis);
  const ris=k.pipe([V(1,.6,1),V(1,8,1)],.1,R,pr,{d0:dis.d1});runs.push(ris);
  const fd=k.pipe([V(1,8,1),V(1,8,10)],.09,R,pr,{d0:ris.d1});runs.push(fd);
  const mn=k.pipe([V(1,8,10),V(29.5,8,10)],.09,R,pr,{d0:fd.d1});runs.push(mn);
  const spr=[],xb=[];for(let x=2.5;x<30;x+=3)xb.push(x);
  xb.forEach(x=>{const d0=fd.d1+(x-1);for(const z1 of [1.5,18.5])runs.push(k.pipe([V(x,8,10),V(x,8,z1)],.035,R,pr,{d0}));
    for(const z of [1.5,4.5,7.5,12.5,15.5,18.5]){const g=new T.Group();g.position.set(x,8,z);pr.add(g);k.tube(V(0,0,0),V(0,-.2,0),.02,0xC9A14A,g);k.cyl(V(0,-.22,0),.08,.015,0xC9A14A,g);k.sph(V(0,-.17,0),.025,C.mal,g);
      spr.push({g,x,z,rem:x>=20&&z>=12,d:d0+Math.abs(z-10)});}});
  k.valve(V(1,1.7,1),'y',.1,C.rojo,pr);k.valve(V(-2.6,.6,4),'x',.1,C.rojo,pr);
  for(const [p,s] of [[V(.18,1.5,16),1],[V(29.82,1.5,4),-1]]){k.box(p,.2,.9,.7,C.rojo);}
  const dmax=Math.max(...runs.map(r=>r.d1)),area=new T.Group(),spray=new T.Group(),agua=new T.Group();k.root.add(area,spray,agua);
  k.box(V(25.2,8.45,15.5),9.6,.02,7.4,C.oro,area,{transparent:true,opacity:.16,emissive:C.oro,emissiveIntensity:.3});
  for(const [p,q] of [[[20.4,11.8],[30,11.8]],[[20.4,19.2],[30,19.2]],[[20.4,11.8],[20.4,19.2]],[[30,11.8],[30,19.2]]])k.bar(V(p[0],8.45,p[1]),V(q[0],8.45,q[1]),.06,.06,C.oro,area);
  const rem=spr.filter(s=>s.rem),cones=[];
  rem.forEach(s=>{const m=new T.Mesh(new T.ConeGeometry(1.5,3.2,22,1,true),L.M(0x8fd3ff,{transparent:true,opacity:.15,side:T.DoubleSide,depthWrite:false,emissive:0x2a6f8f,emissiveIntensity:.5}));m.position.set(s.x,7.8-1.6,s.z);spray.add(m);cones.push(m);});
  const drops=[];rem.forEach(s=>{for(let i=0;i<5;i++){const a=rnd(0,6.28),r=rnd(.2,1.3);drops.push([V(s.x,7.75,s.z),V(s.x+Math.cos(a)*r,4.6,s.z+Math.sin(a)*r)]);}});
  k.flow(drops,0x9fdcff,{n:260,speed:4.5,size:.22},agua);
  const net=rem.map(s=>[V(-7.1,.6,4),V(-1.2,.6,4),V(-1.2,.6,1),V(1,.6,1),V(1,8,1),V(1,8,10),V(s.x,8,10),V(s.x,8,s.z),V(s.x,7.8,s.z)]);
  const nf=k.flow(net,0x9fdcff,{n:280,speed:6.5,size:.34});
